import React, { useState, useEffect } from 'react';
import axios from 'axios';
import FamilyTree from './components/FamilyTree';
import PersonForm from './components/PersonForm';
import PersonDetails from './components/PersonDetails';
import RelationshipForm from './components/RelationshipForm';

const API_URL = 'http://localhost:3001/api';

function App() {
  const [people, setPeople] = useState([]);
  const [selectedPerson, setSelectedPerson] = useState(null);
  const [showPersonForm, setShowPersonForm] = useState(false);
  const [showRelationshipForm, setShowRelationshipForm] = useState(false);
  const [editingPerson, setEditingPerson] = useState(null);
  const [searchQuery, setSearchQuery] = useState('');
  const [treeData, setTreeData] = useState(null);

  useEffect(() => {
    fetchPeople();
    fetchTreeData();
  }, []);

  const fetchPeople = async () => {
    try {
      const response = await axios.get(`${API_URL}/people`);
      setPeople(response.data);
    } catch (error) {
      console.error('Error fetching people:', error);
    }
  };

  const fetchTreeData = async () => {
    try {
      const response = await axios.get(`${API_URL}/tree`);
      setTreeData(response.data);
    } catch (error) {
      console.error('Error fetching tree data:', error);
    }
  };

  const handleAddPerson = async (personData) => {
    try {
      await axios.post(`${API_URL}/people`, personData);
      fetchPeople();
      fetchTreeData();
      setShowPersonForm(false);
    } catch (error) {
      console.error('Error adding person:', error);
      alert('שגיאה בהוספת אדם');
    }
  };

  const handleUpdatePerson = async (personData) => {
    try {
      await axios.put(`${API_URL}/people/${editingPerson.id}`, personData);
      fetchPeople();
      fetchTreeData();
      setEditingPerson(null);
      setShowPersonForm(false);
    } catch (error) {
      console.error('Error updating person:', error);
      alert('שגיאה בעדכון אדם');
    }
  };

  const handleDeletePerson = async (id) => {
    if (!window.confirm('האם אתה בטוח שברצונך למחוק אדם זה?')) return;

    try {
      await axios.delete(`${API_URL}/people/${id}`);
      fetchPeople();
      fetchTreeData();
      setSelectedPerson(null);
    } catch (error) {
      console.error('Error deleting person:', error);
      alert('שגיאה במחיקת אדם');
    }
  };

  const handleAddRelationship = async (relationshipData) => {
    try {
      await axios.post(`${API_URL}/relationships`, relationshipData);
      fetchTreeData();
      setShowRelationshipForm(false);
    } catch (error) {
      console.error('Error adding relationship:', error);
      alert('שגיאה בהוספת קשר');
    }
  };

  const handleSearch = async () => {
    if (!searchQuery.trim()) {
      fetchPeople();
      return;
    }
    try {
      const response = await axios.get(`${API_URL}/search?q=${searchQuery}`);
      setPeople(response.data);
    } catch (error) {
      console.error('Error searching:', error);
    }
  };

  const handleEditPerson = (person) => {
    setEditingPerson(person);
    setShowPersonForm(true);
  };

  return (
    <div className="app">
      <header className="app-header">
        <h1>🌳 עץ שורשים משפחתי</h1>
        <div className="controls">
          <input
            type="text"
            placeholder="חיפוש..."
            className="search-box"
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
            onKeyPress={(e) => e.key === 'Enter' && handleSearch()}
          />
          <button className="btn btn-secondary" onClick={handleSearch}>
            חפש
          </button>
          <button className="btn btn-primary" onClick={() => { setEditingPerson(null); setShowPersonForm(true); }}>
            הוסף אדם
          </button>
          <button className="btn btn-secondary" onClick={() => setShowRelationshipForm(true)}>
            הוסף קשר
          </button>
        </div>
      </header>

      <div className="main-content">
        <div className="sidebar">
          <h2>אנשים</h2>
          {people.map(person => (
            <div key={person.id} className="person-card">
              <h3>{person.first_name} {person.last_name}</h3>
              <p>תאריך לידה: {person.birth_date || 'לא ידוע'}</p>
              <p>מין: {person.gender === 'male' ? 'זכר' : person.gender === 'female' ? 'נקבה' : 'אחר'}</p>
              <div className="person-actions">
                <button className="btn btn-primary" onClick={() => setSelectedPerson(person)}>
                  פרטים
                </button>
                <button className="btn btn-secondary" onClick={() => handleEditPerson(person)}>
                  ערוך
                </button>
                <button className="btn btn-danger" onClick={() => handleDeletePerson(person.id)}>
                  מחק
                </button>
              </div>
            </div>
          ))}
        </div>

        <div className="tree-container">
          {treeData && (
            <FamilyTree 
              data={treeData} 
              onNodeClick={setSelectedPerson}
            />
          )}
        </div>
      </div>

      {showPersonForm && (
        <PersonForm
          person={editingPerson}
          onSubmit={editingPerson ? handleUpdatePerson : handleAddPerson}
          onClose={() => { setShowPersonForm(false); setEditingPerson(null); }}
        />
      )}

      {showRelationshipForm && (
        <RelationshipForm
          people={people}
          onSubmit={handleAddRelationship}
          onClose={() => setShowRelationshipForm(false)}
        />
      )}

      {selectedPerson && (
        <PersonDetails
          person={selectedPerson}
          onClose={() => setSelectedPerson(null)}
        />
      )}
    </div>
  );
}

export default App;
